   169→  box-shadow:
   170→    0 1px 0 var(--inset-glint) inset,
   171→    0 22px 44px rgba(30, 90, 72, 0.1),
   172→    0 6px 18px rgba(23, 58, 64, 0.08);
   173→  backdrop-filter: blur(4px);
   174→}
   175→
   176→.feature-card {
   177→  background: linear-gradient(165deg, color-mix(in oklab, var(--surface-strong) 93%, white 7%), var(--surface));
   178→  box-shadow:
   179→    0 1px 0 var(--inset-glint) inset,
   180→    0 18px 34px rgba(30, 90, 72, 0.1),
   181→    0 4px 14px rgba(23, 58, 64, 0.06);
   182→}
   183→
   184→.feature-card:hover {
   185→  transform: translateY(-2px);
   186→  border-color: color-mix(in oklab, var(--lagoon-deep) 35%, var(--line));
   187→}
   188→
   189→button,
   190→.island-shell,
   191→a {
